const inputs = $('Tipos teste').all();
const outputs = $input.all();
const linhas = [];
for (let i = 0; i < outputs.length; i++) {
  const tipo = inputs[i]?.json?.tipo ?? '?';
  const item = outputs[i];
  if (item.json.error) {
    linhas.push({ tipo, itens_pagina_1: 0, erro: item.json.error.type ?? item.json.error.message ?? 'erro' });
    continue;
  }
  const batch = item.json.data ?? [];
  const count = Array.isArray(batch) ? batch.length : 0;
  const exemplo = count > 0 ? (batch[0].nome ?? batch[0].codigo ?? String(batch[0].id)) : null;
  linhas.push({ tipo, itens_pagina_1: count, exemplo, tem_mais_paginas: count === 100 });
}
return [{ json: { resumo: linhas, total_tipos_com_100: linhas.filter((l) => l.itens_pagina_1 === 100).length } }];
